// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addProductToCart } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(814000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/logout`);

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await addProductToCart(page, "2");
    await expect(page.locator('#cart-count-badge')).toHaveText('2');

    await page.goto(`${baseUrl}/product/66VCHSJNUP`);
    await addProductToCart(page, "3");

    // Badge must equal the SUM of line-item quantities (2 + 3 = 5),
    // not the number of line items (2) or the last quantity added (3).
    await expect(page.locator('#cart-count-badge')).toHaveText('5');
    await expect(page.getByRole("link", { name: "Cart icon" })).toContainText("5");
    await expect(page.getByTestId("cart-heading")).toContainText("Cart (5)");
    await expect(page.getByText("Quantity: 2")).toBeVisible();
    await expect(page.getByText("Quantity: 3")).toBeVisible();
});
